-- Brightside fixture schema (DuckDB). Generated by generate.js from
-- lib/tables.js: edit that file, then run npm run fixture:generate.
-- Money is integer cents; dates are ISO DATE in the local business calendar.

CREATE TABLE zones (
  zone_id VARCHAR PRIMARY KEY,
  name VARCHAR NOT NULL
);

CREATE TABLE packages (
  package_id VARCHAR PRIMARY KEY,
  name VARCHAR NOT NULL,
  base_price_cents BIGINT NOT NULL
);

CREATE TABLE add_ons (
  add_on_id VARCHAR PRIMARY KEY,
  name VARCHAR NOT NULL,
  price_cents BIGINT NOT NULL
);

CREATE TABLE crews (
  crew_id INTEGER PRIMARY KEY,
  zone_id VARCHAR NOT NULL REFERENCES zones (zone_id),
  name VARCHAR NOT NULL,
  base_geo_lat_e6 INTEGER NOT NULL,
  base_geo_lon_e6 INTEGER NOT NULL
);

CREATE TABLE staff (
  staff_id INTEGER PRIMARY KEY,
  name VARCHAR NOT NULL UNIQUE,
  role VARCHAR NOT NULL,
  hire_date DATE NOT NULL,
  end_date DATE,
  hourly_rate_cents BIGINT NOT NULL
);

CREATE TABLE pay_rates (
  rate_id INTEGER PRIMARY KEY,
  staff_id INTEGER NOT NULL REFERENCES staff (staff_id),
  start_date DATE NOT NULL,
  end_date DATE,
  role VARCHAR NOT NULL,
  hourly_rate_cents BIGINT NOT NULL,
  UNIQUE (staff_id, start_date)
);

CREATE TABLE crew_memberships (
  membership_id INTEGER PRIMARY KEY,
  crew_id INTEGER NOT NULL REFERENCES crews (crew_id),
  staff_name VARCHAR NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE,
  staff_id INTEGER NOT NULL REFERENCES staff (staff_id)
);

CREATE TABLE clients (
  client_id INTEGER PRIMARY KEY,
  zone_id VARCHAR NOT NULL REFERENCES zones (zone_id),
  first_name VARCHAR NOT NULL,
  last_name VARCHAR NOT NULL,
  email VARCHAR NOT NULL UNIQUE,
  phone VARCHAR NOT NULL,
  created_on DATE NOT NULL
);

CREATE TABLE properties (
  property_id INTEGER PRIMARY KEY,
  client_id INTEGER NOT NULL REFERENCES clients (client_id),
  street_address VARCHAR NOT NULL,
  city VARCHAR NOT NULL,
  postal_code VARCHAR NOT NULL,
  home_type VARCHAR NOT NULL,
  square_feet INTEGER NOT NULL,
  bedrooms INTEGER NOT NULL,
  bathrooms DECIMAL(3,1) NOT NULL,
  has_pets BOOLEAN NOT NULL,
  access_method VARCHAR NOT NULL,
  geo_lat_e6 INTEGER NOT NULL,
  geo_lon_e6 INTEGER NOT NULL
);

CREATE TABLE plans (
  plan_id INTEGER PRIMARY KEY,
  property_id INTEGER NOT NULL REFERENCES properties (property_id),
  package_id VARCHAR NOT NULL REFERENCES packages (package_id),
  frequency VARCHAR NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE,
  status VARCHAR NOT NULL,
  start_price_cents BIGINT NOT NULL,
  price_cents BIGINT NOT NULL
);

CREATE TABLE plan_price_changes (
  change_id INTEGER PRIMARY KEY,
  plan_id INTEGER NOT NULL REFERENCES plans (plan_id),
  effective_date DATE NOT NULL,
  old_price_cents BIGINT NOT NULL,
  new_price_cents BIGINT NOT NULL,
  UNIQUE (plan_id, effective_date)
);

CREATE TABLE visits (
  visit_id INTEGER PRIMARY KEY,
  property_id INTEGER NOT NULL REFERENCES properties (property_id),
  plan_id INTEGER REFERENCES plans (plan_id),
  crew_id INTEGER NOT NULL REFERENCES crews (crew_id),
  package_id VARCHAR NOT NULL REFERENCES packages (package_id),
  visit_date DATE NOT NULL,
  status VARCHAR NOT NULL,
  arrival_window VARCHAR NOT NULL,
  scheduled_start TIME NOT NULL,
  scheduled_minutes INTEGER NOT NULL,
  route_order INTEGER NOT NULL,
  travel_minutes_from_previous INTEGER NOT NULL
);

CREATE TABLE invoices (
  invoice_id INTEGER PRIMARY KEY,
  client_id INTEGER NOT NULL REFERENCES clients (client_id),
  visit_id INTEGER NOT NULL UNIQUE REFERENCES visits (visit_id),
  issued_on DATE NOT NULL,
  due_on DATE NOT NULL,
  total_cents BIGINT NOT NULL
);

CREATE TABLE invoice_lines (
  line_id INTEGER PRIMARY KEY,
  invoice_id INTEGER NOT NULL REFERENCES invoices (invoice_id),
  package_id VARCHAR REFERENCES packages (package_id),
  add_on_id VARCHAR REFERENCES add_ons (add_on_id),
  quantity INTEGER NOT NULL,
  amount_cents BIGINT NOT NULL
);

CREATE TABLE payments (
  payment_id INTEGER PRIMARY KEY,
  invoice_id INTEGER NOT NULL REFERENCES invoices (invoice_id),
  paid_on DATE NOT NULL,
  amount_cents BIGINT NOT NULL,
  method VARCHAR NOT NULL
);

CREATE TABLE timesheets (
  timesheet_id INTEGER PRIMARY KEY,
  visit_id INTEGER NOT NULL REFERENCES visits (visit_id),
  staff_id INTEGER NOT NULL REFERENCES staff (staff_id),
  clock_in TIMESTAMP NOT NULL,
  clock_out TIMESTAMP NOT NULL,
  minutes INTEGER NOT NULL
);

CREATE TABLE scheduled_visits (
  scheduled_visit_id INTEGER PRIMARY KEY,
  property_id INTEGER NOT NULL REFERENCES properties (property_id),
  plan_id INTEGER NOT NULL REFERENCES plans (plan_id),
  crew_id INTEGER NOT NULL REFERENCES crews (crew_id),
  package_id VARCHAR NOT NULL REFERENCES packages (package_id),
  visit_date DATE NOT NULL,
  status VARCHAR NOT NULL,
  status_changed_on DATE NOT NULL,
  arrival_window VARCHAR NOT NULL,
  scheduled_start TIME NOT NULL,
  scheduled_minutes INTEGER NOT NULL,
  labour_minutes INTEGER NOT NULL,
  route_order INTEGER NOT NULL,
  travel_minutes_from_previous INTEGER NOT NULL
);

CREATE TABLE service_rules (
  rule_id INTEGER PRIMARY KEY,
  property_id INTEGER NOT NULL REFERENCES properties (property_id),
  rule_type VARCHAR NOT NULL,
  value VARCHAR NOT NULL,
  strength VARCHAR NOT NULL,
  UNIQUE (property_id, rule_type)
);

CREATE TABLE staff_absences (
  absence_id INTEGER PRIMARY KEY,
  staff_id INTEGER NOT NULL REFERENCES staff (staff_id),
  absence_date DATE NOT NULL,
  reported_on DATE NOT NULL,
  UNIQUE (staff_id, absence_date)
);

CREATE TABLE depots (
  depot_id VARCHAR PRIMARY KEY,
  name VARCHAR NOT NULL,
  geo_lat_e6 INTEGER NOT NULL,
  geo_lon_e6 INTEGER NOT NULL
);

CREATE TABLE fixture_meta (
  key VARCHAR PRIMARY KEY,
  value VARCHAR NOT NULL
);
